  function epodBody(e) { return `<div class="da-sub">${DT('Время', 'Zeit', 'Time', 'Уақыт')}: ${esc(e.at)} · ${DT('координаты', 'Position', 'position', 'координаттар')}: ${e.lat}, ${e.lon}</div><div class="da-sub">${DT('Температурный отчёт', 'Temperaturbericht', 'Temperature report', 'Температура есебі')}: ${String(e.temp.min).replace('.', ',')}…${String(e.temp.max).replace('.', ',')} °C · ${e.temp.ok ? '<span class="da-ok">' + DT('в норме', 'im Bereich', 'in range', 'қалыпты') + '</span>' : '<span class="da-bad">' + DT('отклонение', 'Abweichung', 'excursion', 'ауытқу') + '</span>'}</div><div class="da-sub">${DT('Подписал', 'Unterschrieben von', 'Signed by', 'Қол қойған')}: ${esc(e.signer)} (${esc(e.role)}) · ${DT('фото', 'Foto', 'photo', 'фото')} ${e.photo}</div>${e.sigHash ? `<div class="da-sub" data-epod-sig>✍ SHA-256 ${esc(e.sigHash)} · 📷 SHA-256 ${esc(e.photo || '—')}</div>` : ''}${e.exp ? `<div class="da-sub" data-epod-scan>${DT('Сканировано', 'Gescannt', 'Scanned', 'Сканерленді')} ${e.scanned} / ${e.exp}${e.stop ? ' · ' + esc(e.stop) : ''}</div>` : ''}`; }
