  const view = admin => `${admin ? howNote('drvOnly') : ''}<div class="da-wrap">${phone()}${side(admin)}</div>`;
  SHELL_NAV.driver.push(['driverapp', 'user', T('Приложение водителя', 'Fahrer-App', 'Driver app', 'Жүргізуші қосымшасы'), 0]);
  SCREENS.driverapp = { title: () => T('Приложение водителя', 'Fahrer-App', 'Driver app', 'Жүргізуші қосымшасы'), sub: () => T('Смена, маршрут, точка с ePOD, возвраты, топливо, сообщения — офлайн-очередь и SMS-режим', 'Schicht, Route, Stopp mit ePOD, Rückläufer, Tanken, Nachrichten — Offline-Warteschlange und SMS-Modus', 'Shift, route, stop with ePOD, returns, fuel, messages — offline queue and SMS mode', 'Ауысым, маршрут, ePOD нүктесі, қайтару, отын, хабарламалар — офлайн кезек және SMS режимі'), body: () => view(S.role !== 'driver') };
